// LinkedIn / Indeed / Naukri do not offer a public job-search API, and scraping
// them breaks their terms. What you ARE allowed to do is read the job-alert
// emails they send you. This turns those emails into rows.
//
// Identity comes from the site + job id in the URL, which is stable across the
// same alert arriving twice. Title/company are best-effort from the anchor text.
const SOURCES = [
  {
    source: 'linkedin',
    url: /https?:\/\/[a-z.]*linkedin\.com\/(?:comm\/)?jobs\/view\/(\d{6,})[^\s"'<>)]*/gi,
    id: /linkedin\.com\/(?:comm\/)?jobs\/view\/(\d{6,})/i,
  },
  {
    source: 'indeed',
    url: /https?:\/\/[a-z.]*indeed\.[a-z.]+\/(?:viewjob\?jk=|rc\/clk\?[^\s"'<>)]*?jk=)([a-z0-9]{8,})[^\s"'<>)]*/gi,
    id: /[?&]jk=([a-z0-9]{8,})/i,
  },
  {
    source: 'naukri',
    url: /https?:\/\/[a-z.]*naukri\.com\/job-listings-[^\s"'<>)]*?-(\d{6,})[^\s"'<>)]*/gi,
    id: /naukri\.com\/job-listings-[^\s"'<>)]*?-(\d{6,})/i,
  },
];

const text = (v) => (v === null || v === undefined ? '' : String(v));
const clean = (s) => text(s).replace(/<[^>]*>/g, ' ').replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ')
  .replace(/&#\d+;/g, ' ').replace(/\s+/g, ' ').trim();

function fingerprint(seed) {
  try {
    const crypto = require('crypto');
    return crypto.createHash('sha256').update(seed).digest('hex').slice(0, 32);
  } catch (e) {
    let h = 2166136261;
    for (let i = 0; i < seed.length; i++) { h ^= seed.charCodeAt(i); h = Math.imul(h, 16777619); }
    return 'fnv' + (h >>> 0).toString(16) + seed.length;
  }
}

// Naukri URLs carry the title as a slug: /job-listings-software-engineer-bangalore-1234567
function titleFromSlug(url) {
  const m = url.match(/job-listings-([a-z0-9-]+?)-\d{6,}/i);
  if (!m) return '';
  return m[1].split('-').filter((w) => w && !/^\d+$/.test(w)).join(' ').replace(/\b\w/g, (c) => c.toUpperCase());
}

// In HTML the link text is usually "Job title at Company" or just the title.
function anchorTextFor(html, url) {
  const esc = url.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re = new RegExp('<a[^>]+href="' + esc + '"[^>]*>([\\s\\S]{0,300}?)</a>', 'i');
  const m = html.match(re);
  return m ? clean(m[1]) : '';
}

const out = [];
const seen = new Set();

for (const item of $input.all()) {
  const j = item.json || {};
  const subject = clean(j.subject || '');
  const html = text(j.html || j.textHtml || j.text || j.textPlain);

  // Optional noise filter: only parse things that look like a job alert.
  if (subject && !/job|alert|career|opening|hiring|recommend|vacanc/i.test(subject)) continue;

  for (const src of SOURCES) {
    src.url.lastIndex = 0;
    const links = html.match(src.url) || [];
    for (const rawLink of links) {
      const link = rawLink.replace(/[),.;]+$/, '');
      const idm = link.match(src.id);
      if (!idm || !idm[1]) continue;
      const jobId = idm[1];
      const key = src.source + ':' + jobId;
      if (seen.has(key)) continue;
      seen.add(key);

      let anchor = anchorTextFor(html, link);
      let title = anchor;
      let company = '';
      const at = anchor.split(/\s+at\s+/i);
      if (at.length === 2) {
        title = at[0].trim();
        company = at[1].trim();
      }
      if (!title || title.length < 4) title = titleFromSlug(link);
      if (!title) title = src.source + ' job ' + jobId;

      out.push({
        source: src.source,
        external_id: key,
        title: title.slice(0, 180),
        company: (company || 'unknown').slice(0, 120),
        location: '',
        url: link,
        description: '',
        salary_text: '',
        tags: [],
        posted_at: j.date || null,
        fingerprint: fingerprint(key),
      });
    }
  }
}

if (!out.length) {
  return [{ json: { empty: true, note: 'no LinkedIn/Indeed/Naukri job links found in these emails' } }];
}
return out.map((row) => ({ json: row }));

// One INSERT per 75 rows, with ON CONFLICT DO NOTHING so re-running the
// workflow is safe (idempotency lives in the database, not in the code).
const items = $input.all().map((i) => i.json).filter((r) => r && r.fingerprint);
if (!items.length) return [{ json: { rows: 0, sql: 'SELECT 1;' } }];

const esc = (v) =>
  v === null || v === undefined || v === ''
    ? 'NULL'
    : "'" + String(v).replace(/\u0000/g, '').replace(/'/g, "''") + "'";

const jsonb = (v) =>
  "'" + JSON.stringify(Array.isArray(v) ? v : []).replace(/'/g, "''") + "'::jsonb";

const stamp = (v) => {
  if (!v) return 'NULL';
  const d = new Date(v);
  return isNaN(d.getTime()) ? 'NULL' : "'" + d.toISOString() + "'::timestamptz";
};

const CHUNK = 75;
const chunks = [];
for (let i = 0; i < items.length; i += CHUNK) chunks.push(items.slice(i, i + CHUNK));

return chunks.map((rows, idx) => ({
  json: {
    chunk: idx + 1,
    rows: rows.length,
    sql:
      'INSERT INTO jobs (source, external_id, title, company, location, country, url, description, salary_text, tags, fingerprint, posted_at) VALUES ' +
      rows
        .map(
          (r) =>
            '(' +
            [
              esc(r.source),
              esc(r.external_id),
              esc(r.title),
              esc(r.company),
              esc(r.location),
              // undefined for rows that carry no location (alert emails) -> NULL
              esc(r.country),
              esc(r.url),
              esc(r.description),
              esc(r.salary_text),
              jsonb(r.tags),
              esc(r.fingerprint),
              stamp(r.posted_at),
            ].join(',') +
            ')'
        )
        .join(',') +
      ' ON CONFLICT (fingerprint) DO NOTHING RETURNING id;',
  },
}));

const fetched = $('Parse alert emails').all().filter((i) => i.json && i.json.fingerprint).length;
const offered = $('Build SQL chunks').all().reduce((n, i) => n + (i.json.rows || 0), 0);
let inserted = 0;
for (const i of $input.all()) {
  const j = i.json || {};
  if (Array.isArray(j)) inserted += j.length;
  else if (Array.isArray(j.rows)) inserted += j.rows.length;
  else if (j.id !== undefined) inserted += 1;
}
return [{ json: { source: 'email-alert', links_found: fetched, unique_in_batch: offered, new_rows: inserted, duplicates_skipped: Math.max(offered - inserted, 0) } }];
